#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
double previous=0,tolerance=1e-9;
for(int n=2;n<=2048;n*=2){
    double step=1.0/n,sum=0;
    for(int i=0;i<=n;i++){
        double x=i*step,weight=i==0||i==n?1:(i%2?4:2);
        sum+=weight*exp(x);
    }
    double estimate=sum*step/3;
    if(n>2&&fabs(estimate-previous)<tolerance){
        cout<<n<<" "<<fixed<<setprecision(12)<<estimate<<"\n";break;
    }
    previous=estimate;
}
return 0;
}

