#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<vector<double>>price={{100,102,101,105},{100,98,96,99},{100,110,108,111}};
double strike=100,rate=0.03,maturity=1,expectedPayoff=0;
for(const auto& path:price){
    double mean=0;
    for(double value:path)mean+=value/path.size();
    expectedPayoff+=max(0.0,mean-strike)/price.size();
}
cout<<"discounted Asian call "<<exp(-rate*maturity)*expectedPayoff<<"\n";
return 0;
}
